const globeZoomFor=element=>element.clientWidth<=430?0:element.clientWidth<=760?0.45:0.85;
const researchResolutionForZoom=zoom=>Number(zoom)<2.5?1:Number(zoom)<4.5?2:Number(zoom)<6.5?3:4;
const loadForecastLayerPreference=()=>{try{const saved=localStorage.getItem(FORECAST_LAYER_PREFERENCE);return saved===null?true:saved==='on'}catch{return true}};
const saveForecastLayerPreference=enabled=>{try{localStorage.setItem(FORECAST_LAYER_PREFERENCE,enabled?'on':'off')}catch{}}

function loadMapLibre(){
  if(window.maplibregl)return Promise.resolve(window.maplibregl);
  if(!document.querySelector(`link[href="${MAPLIBRE_CSS}"]`)){const link=document.createElement('link');link.rel='stylesheet';link.href=MAPLIBRE_CSS;document.head.append(link)}
  return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=MAPLIBRE_JS;script.onload=()=>resolve(window.maplibregl);script.onerror=()=>reject(new Error('map library unavailable'));document.head.append(script)});
}

async function loadEvents(){
  const response=await fetch('./data/world/validation-events.json');if(!response.ok)throw new Error('validation events unavailable');
  const data=await response.json();return data.events.map(validateWorldEvent);
}

async function loadResearchPreview(){
  const response=await fetch('./data/world/earthquake-research-preview-v1.json');if(!response.ok)throw new Error('research preview unavailable');
  const data=await response.json();if(data.schemaId!=='koyomi-earthquake-research-preview-v1'||data.realHoldoutExecuted!==false||data.bandMethod!=='target-specific-all-horizon-fixed-quantiles-v1'||!Array.isArray(data.rows))throw new Error('invalid research preview');return data;
}

async function loadResearchCatalog(){
  const response=await fetch('./data/world/earthquake-research-catalog-v2.json');if(!response.ok)throw new Error('research catalog unavailable');
  const data=await response.json();if(data.schemaId!=='koyomi-earthquake-research-catalog-v2'||data.freshness?.complete!==true||!data.eventsByCell||!Number.isFinite(data.latestTimeUtcMs)||!/^[a-f0-9]{64}$/i.test(data.inputSha256||''))throw new Error('invalid research catalog');return data;
}

