const color=score=>score>=80?'#b42318':score>=70?'#e46f19':score>=40?'#d9a514':'#1e7f68';
const localInputValue=date=>{const d=new Date(date),offset=d.getTimezoneOffset()*60000;return new Date(d-offset).toISOString().slice(0,16)};
const contributorState=item=>item.status==='unavailable'?'計算不能':item.active?'高反応':'低反応';
const motionLabel=value=>({applying:'接近中',separating:'離反中',stationary:'変化僅少',unknown:'判定不能'}[value]||'判定不能');
const calculationQualityLabel=value=>({complete:'完全',partial:'一部不足',unavailable:'計算不能'}[value]||'未指定');
const ephemerisLabel=metadata=>metadata.ephemerisId==='astronomy-engine'?'Astronomy Engine':metadata.ephemerisPrecision==='fallback'?'内蔵近似計算':'天文計算エンジン';
const precisionLabel=value=>({high:'高精度',fallback:'近似',unspecified:'未指定'}[value]||'検証用');
const angleQualityNote=value=>value==='high-latitude'?'／高緯度のため地域角精度に注意':value==='unavailable'?'／極域の地域角は計算対象外':'';
const contributorDetails=item=>(item.details||[]).map(detail=>{
  if(detail.bodies)return`${detail.bodies.join('―')} ${detail.aspectAngle}°／離角 ${detail.separation.toFixed(2)}°／オーブ ${detail.orb.toFixed(2)}°／${motionLabel(detail.motion)}`;
  if(detail.body)return`${detail.body}―${detail.angle}／オーブ ${detail.orb.toFixed(2)}°／${motionLabel(detail.motion)}`;
  return`${detail.phase}側／離角 ${detail.separation.toFixed(2)}°／オーブ ${detail.orb.toFixed(2)}°／${motionLabel(detail.motion)}`;
}).map(text=>`<small>${esc(text)}</small>`).join('');

function shell(events,forecastLayerDefault){return `<section class="world-map-shell" id="worldMapShell" aria-labelledby="worldMapTitle"><header class="world-map-head"><div><span class="world-map-kicker">こよみ世情</span><h2 id="worldMapTitle">世界の世情地球儀</h2></div><div class="world-mode" role="group" aria-label="表示モード"><button class="active" data-world-mode="forecast">未来を見る</button><button data-world-mode="validation">過去検証</button></div></header><div class="world-controls"><label>日時<input id="worldDateTime" type="datetime-local" value="${localInputValue(new Date())}"></label><label>テーマ<select id="worldTheme"><option value="earthquake">地震</option><option disabled>火山（準備中）</option><option disabled>気象（準備中）</option><option disabled>戦争・紛争（準備中）</option></select></label><label id="worldEventField" hidden>過去事象<select id="worldEvent">${events.map(item=>`<option value="${item.id}">${esc(item.label)}</option>`).join('')}</select></label></div><div class="world-layer-control"><label for="earthquakeForecastLayer"><span><b>地震予測・研究プレビュー</b><small id="earthquakeForecastLayerState">${forecastLayerDefault?'研究プレビュー・検証中':'OFF'}</small></span><input id="earthquakeForecastLayer" type="checkbox" role="switch" aria-describedby="earthquakeForecastLayerNote" ${forecastLayerDefault?'checked':''}></label><div class="world-preview-mode" role="group" aria-label="地震研究プレビュー表示"><button class="active" data-preview-mode="change" type="button">変化</button><button data-preview-mode="current" type="button">現在値</button><button data-preview-mode="outcomes" type="button">実績</button></div><div class="world-preview-selectors"><label class="world-horizon">対象規模<select id="earthquakePreviewMagnitude"><option value="4.5">M4.5以上・活動度</option><option value="6.5" selected>M6.5以上・大地震注意度</option></select></label><label class="world-horizon">予測期間<select id="earthquakePreviewHorizon"><option>1</option><option>3</option><option>7</option><option>14</option><option selected>30</option></select>日</label></div><label class="world-outcome-toggle" for="earthquakeOutcomeLayer"><span><b>その後の実績を重ねる</b><small>変化・現在値にも事後確認データを重ねます</small></span><input id="earthquakeOutcomeLayer" type="checkbox" role="switch" checked></label><p id="earthquakeForecastLayerNote">各セル自身の過去と比べた「平常比」を表示します。地震の発生確率ではありません。</p><div class="world-preview-legend" data-preview-mode="change" data-target-magnitude="6.5"><span>平常域</span><i></i><i></i><i></i><i></i><span>大きく上昇</span><span class="world-pattern-key"><em class="hatch"></em>斜線 急静穏化</span><span class="world-pattern-key"><em class="dots"></em>点 地磁気研究</span><span class="world-pattern-key">↑ 上昇傾向</span><b class="world-outcome-key">● 期間内地震</b></div></div><div class="world-map-stage"><div id="worldMap" role="application" aria-label="回転できる世界の世情傾向地球儀"></div><div id="worldMapStatus" class="world-map-status">地球儀を読み込んでいます…</div><aside id="earthOmenRanking" class="world-omen-ranking" aria-label="星の兆しが強い場所"></aside><aside id="earthquakeChangeRanking" class="world-change-ranking" aria-label="変化上位" hidden></aside><button id="worldGlobeReset" class="world-globe-reset" type="button">◎ 地球全体</button></div><p class="world-disclaimer">地球儀をドラッグして地域を選べます。占術・暦等を用いた実験的指標であり、科学的な地震予知ではありません。防災判断では公的機関の情報を優先してください。</p><div class="world-sheet" id="worldSheet" aria-live="polite"><div class="world-sheet-grip"></div><div id="worldSheetBody"><b>地球儀上の地域をタップ</b><p>地震研究とマンデン占術を独立したカードで確認できます。</p></div></div></section>`}

function visibleCells(map,grid,lockedResolution=null){
  const bounds=map.getBounds(),box={south:bounds.getSouth(),north:bounds.getNorth(),west:bounds.getWest(),east:bounds.getEast()};let resolution=lockedResolution??grid.resolutionForZoom(map.getZoom()),ids=grid.viewportCells(box,resolution,MAX_VISIBLE_CELLS);
  while(ids.length>=MAX_VISIBLE_CELLS&&resolution>0){resolution-=1;ids=grid.viewportCells(box,resolution,MAX_VISIBLE_CELLS)}
  return {ids,resolution};
}

export function spatialCellMatches(grid,displayCellId,sourceCellId,sourceResolution){
  const displayResolution=grid.resolution(displayCellId),source=String(sourceCellId);
  if(displayResolution===sourceResolution)return String(displayCellId)===source;
  if(displayResolution>sourceResolution)return grid.parent(displayCellId,sourceResolution)===source;
  return grid.parent(source,displayResolution)===String(displayCellId);
}

